// Agent-Tool-Input lesen
const inp = $input.first().json;
const code = inp.query || inp.input || inp.code || inp.programCode || '';

const VALID_COMMANDS = ['GET','GETNOT','DUP','NOT','AND','OR','XOR','MOV','CMOV','SET','CSET','CINC','CDEC','CMP','GT','LE'];

const STACK_EFFECTS = {
  'GET':   { pop: 0, push: 1 }, 'GETNOT': { pop: 0, push: 1 },
  'NOT': { pop: 1, push: 1 },
  'AND':   { pop: 2, push: 1 }, 'OR': { pop: 2, push: 1 }, 'XOR': { pop: 2, push: 1 },
  'MOV':   { pop: 1, push: 0 }, 'CMOV': { pop: 1, push: 0 },
  'SET':   { pop: 0, push: 0 }, 'CSET': { pop: 1, push: 0 },
  'CINC':  { pop: 1, push: 0 }, 'CDEC': { pop: 1, push: 0 },
  'CMP':   { pop: 0, push: 1 }, 'GT': { pop: 0, push: 1 }, 'LE': { pop: 0, push: 1 }
};

const LIMITS = { 'I': 64, 'O': 64, 'M': 1024, 'T': 128, 'C': 128 };

// Erlaubte Operand-Typen pro Befehl (erster Operand nach dem Befehlsnamen)
const ALLOWED_SUBJECTS = {
  'GET':   ['I','O','M','T'],      // GET C existiert NICHT
  'GETNOT':['I','O','M','T'],      // GETNOT C existiert NICHT
  'MOV':   ['O','M'],              // MOV C existiert NICHT
  'CMOV':  ['O','M'],              // CMOV C existiert NICHT
  'SET':   ['T','C'],              // SET I/O/M existiert NICHT
  'CSET':  ['T','C'],              // CSET I/O/M existiert NICHT
  'CINC':  ['C'],                  // nur Counter
  'CDEC':  ['C'],                  // nur Counter
  'CMP':   ['C'],                  // nur Counter
  'GT':    ['C'],                  // nur Counter
  'LE':    ['C'],                  // nur Counter
};

const lines = code.split('\n').map(l => l.trim()).filter(l => l.length > 0);
const errors = [];
const trace = [];
let depth = 0;
let lineNum = 0;

for (const line of lines) {
  lineNum++;
  if (line.startsWith('#')) { trace.push({ l: lineNum, i: line, d: depth, comment: true }); continue; }
  const parts = line.split(/\s+/);
  const cmd = parts[0].toUpperCase();

  if (!VALID_COMMANDS.includes(cmd)) {
    errors.push(`Zeile ${lineNum}: Unbekannter Befehl '${cmd}'`);
    continue;
  }

  // DUP-Sonderbehandlung: DUP ohne Arg = Value 2, Loop laeuft k-1 mal
  if (cmd === 'DUP') {
    const k = parts.length >= 2 ? parseInt(parts[1]) : 2;
    if (isNaN(k) || k < 0) {
      errors.push(`Zeile ${lineNum}: DUP-Argument '${parts[1]}' ungueltig`);
      continue;
    }
    if (k === 1) errors.push(`Zeile ${lineNum}: FEHLER: 'DUP 1' ist ein NOP (0 Pushes) — Stack unveraendert! Verwende DUP ohne Argument.`);
    if (k > 1 && depth < 1) errors.push(`Zeile ${lineNum}: Stack-Unterlauf bei 'DUP' (braucht 1, hat ${depth})`);
    const beforeDup = depth;
    const pushCount = Math.max(0, k - 1);
    depth += pushCount;
    trace.push({ l: lineNum, i: line, before: beforeDup, after: depth });
    continue;
  }

  const fx = STACK_EFFECTS[cmd];
  const before = depth;
  const minReq = fx.needsMin || fx.pop;

  if (depth < minReq)
    errors.push(`Zeile ${lineNum}: Stack-Unterlauf bei '${cmd}' (braucht ${minReq}, hat ${depth})`);

  // Operand-Typ und Adresse pruefen (fuer Befehle mit Subjekt + Adresse)
  if (ALLOWED_SUBJECTS[cmd] && parts.length >= 2) {
    const subj = parts[1].toUpperCase();
    const allowed = ALLOWED_SUBJECTS[cmd];

    // Sonderfall GET/GETNOT: GET 0 / GET 1 sind Konstanten (kein Subjekt)
    const isConstant = (cmd === 'GET') && (parts[1] === '0' || parts[1] === '1');

    if (!isConstant) {
      if (!allowed.includes(subj)) {
        errors.push(`Zeile ${lineNum}: '${cmd} ${subj}' ist ungueltig — ${cmd} erlaubt nur: ${allowed.join('/')}`);
      } else if (parts.length >= 3) {
        const addr = parseInt(parts[2]);
        if (LIMITS[subj] !== undefined && (isNaN(addr) || addr < 0 || addr >= LIMITS[subj]))
          errors.push(`Zeile ${lineNum}: Adresse ${parts[2]} ungueltig fuer ${subj} (erlaubt: 0-${LIMITS[subj]-1})`);
      }
    }
  }

  depth = Math.max(0, depth - fx.pop + fx.push);
  trace.push({ l: lineNum, i: line, before, after: depth });
}

if (depth !== 0) errors.push(`Stack nicht leer am Ende: Tiefe=${depth}`);

const valid = errors.length === 0;
let result = `Validierung: ${valid ? 'GUELTIG' : 'FEHLERHAFT'}\n`;
if (!valid) { result += 'Fehler:\n' + errors.map(e => `- ${e}`).join('\n') + '\n'; }
result += 'Stack-Trace:\n' + trace.filter(t => !t.comment).map(t => `  ${t.l}: [${t.before}] ${t.i} [${t.after}]`).join('\n');
return result;

// Holt das aktuell in der Steuerung geladene Programm von der Desktop App API
try {
  const response = await $http.request({
    method: 'GET',
    url: 'http://localhost:5555/api/program',
    returnFullResponse: true
  });

  const body = response.body;

  // Body als String (JSON-Text)
  if (typeof body === 'string') {
    try {
      const parsed = JSON.parse(body);
      if (parsed.programCode) return `Programm von Steuerung geladen (${parsed.sourceLines || '?'} Zeilen):\n\n${parsed.programCode}`;
      if (parsed.source) return `Programm von Steuerung geladen:\n\n${parsed.source}`;
      return body;
    } catch {
      return body;
    }
  }

  // Body als Objekt (n8n hat bereits geparst)
  if (body && body.programCode) {
    return `Programm von Steuerung geladen (${body.sourceLines || '?'} Zeilen):\n\n${body.programCode}`;
  }
  if (body && body.source) {
    return `Programm von Steuerung geladen:\n\n${body.source}`;
  }

  return `Steuerung erreichbar, aber kein Programm geladen. Antwort: ${JSON.stringify(body)}`;

} catch (e) {
  return `FEHLER: Steuerung nicht erreichbar. Ist die FPC Desktop App gestartet? Details: ${e.message}`;
}
